  "evidence": [
    {
      "employee_quote": "我主要負責公司的線上訂單系統。",
      "reference_quote": "從事印刷生產作業安排與流程控管等工作。"
    },
    {
      "employee_quote": "我也會寫處理訂單的 API、權限檢查和商業規則，設計及修改資料表、查詢與資料更新",
      "reference_quote": "建檔於庫存管理電腦系統"
    },
    {
      "employee_quote": "畫面與伺服器功能都是我持續負責的主要工作。",
      "reference_quote": "規劃生產排程,考量人力、設備及產能,進行工作分配,以降低成本並提高效率。"
    }
  ],
  "limitations": [
    "公版提及客戶訂單規格及庫存管理電腦系統，但內容是印刷生產安排、庫存記錄等作業，沒有支持軟體介面或伺服器功能的開發及維護。",
    "員工偶爾協助同事處理網路問題，不足以使此公版代表其主要工作。"
  ]
}
